Container.prototype.renderBoundings = function() {
  const instance = this.instance;
  const cx = instance.cx | 0;
  const cy = instance.cy | 0;
  const cr = instance.cr;
  const buffer = instance.cache.fg;
  const lw = Math.max(0.55, 0.55 * cr);
