    const response = await this.api.fetch(`gists/${id}`, opts);
    if (!response.ok) {
      throw new Error('unable to patch gist');
    }

    const g = await response.json();
    return fromGitHubGist(g);
  }

  async create(gist) {
    const opts = {
      method: 'POST',
