else:
raise
assert self.text

def __repr__(self):
if self.headline:
headline = ' '.join(self.headline.leaves())
else:
headline = ' '.join([w for w in self.text.leaves()
if w[:1] != '<'][:11])+'...'
if self.docno is not None:
return '<MUCDocument %s: %r>' % (self.docno, headline)
else:
return '<MUCDocument: %r>' % headline

