    job_row = self.api_submit_job(job)

    while not job_row.status.worker_done():
        job_row = self.api_get_job(job_row.id)
        time.sleep(pool_interval)

    output_blob = self.api_get_job_output(job_row.id)

    if job_row.status.failed():
