        tabsArray.add(Messages.getString(locale, "RSSConnector.Bandwidth"));
        tabsArray.add(Messages.getString(locale, "RSSConnector.Proxy"));
        out.print("<script type=\"text/javascript\">\n" + "<!--\n" + "function checkConfig()\n" + "{\n" + "  if (editconnection.email.value != \"\" && editconnection.email.value.indexOf(\"@\") == -1)\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.NeedAValidEmailAddress") + "\");\n" + "    editconnection.email.focus();\n" + "    return false;\n" + "  }\n" + "  if (editconnection.bandwidth.value != \"\" && !isInteger(editconnection.bandwidth.value))\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.EnterAValidNumberOrBlankForNoLimit") + "\");\n" + "    editconnection.bandwidth.focus();\n" + "    return false;\n" + "  }\n" + "  if (editconnection.connections.value == \"\" || !isInteger(editconnection.connections.value))\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.EnterAValidNumberForTheMaxNumberOfOpenConnectionsPerServer") + "\");\n" + "    editconnection.connections.focus();\n" + "    return false;\n" + "  }\n" + "  if (editconnection.fetches.value != \"\" && !isInteger(editconnection.fetches.value))\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.EnterAValidNumberOrBlankForNoLimit") + "\");\n" + "    editconnection.fetches.focus();\n" + "    return false;\n" + "  }\n" + "  return true;\n" + "}\n" + "\n" + "function checkConfigForSave()\n" + "{\n" + "  if (editconnection.email.value == \"\")\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.EmailAddressRequiredToBeIncludedInAllRequestHeaders") + "\");\n" + "    SelectTab(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.Email") + "\");\n" + "    editconnection.email.focus();\n" + "    return false;\n" + "  }\n" + "  return true;\n" + "}\n" + "\n" + "//-->\n" + "</script>\n");
    }

