        out.print("<script type=\"text/javascript\">\n" + "<!--\n" + "function " + seqPrefix + "SpecOp(n, opValue, anchorvalue)\n" + "{\n" + "  eval(\"editjob.\"+n+\".value = \\\"\"+opValue+\"\\\"\");\n" + "  postFormSetAnchor(anchorvalue);\n" + "}\n" + "\n" + "function " + seqPrefix + "AddRegexp(anchorvalue)\n" + "{\n" + "  if (editjob." + seqPrefix + "rssmatch.value == \"\")\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.MatchMustHaveARegexpValue") + "\");\n" + "    editjob." + seqPrefix + "rssmatch.focus();\n" + "    return;\n" + "  }\n" + "\n" + "  " + seqPrefix + "SpecOp(\"" + seqPrefix + "rssop\",\"Add\",anchorvalue);\n" + "}\n" + "\n" + "function " + seqPrefix + "RemoveRegexp(index, anchorvalue)\n" + "{\n" + "  editjob." + seqPrefix + "rssindex.value = index;\n" + "  " + seqPrefix + "SpecOp(\"" + seqPrefix + "rssop\",\"Delete\",anchorvalue);\n" + "}\n" + "\n" + "function " + seqPrefix + "SpecAddToken(anchorvalue)\n" + "{\n" + "  if (editjob." + seqPrefix + "spectoken.value == \"\")\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.TypeInAnAccessToken") + "\");\n" + "    editjob." + seqPrefix + "spectoken.focus();\n" + "    return;\n" + "  }\n" + "  " + seqPrefix + "SpecOp(\"" + seqPrefix + "accessop\",\"Add\",anchorvalue);\n" + "}\n" + "\n" + "function " + seqPrefix + "URLRegexpDelete(index, anchorvalue)\n" + "{\n" + "  editjob." + seqPrefix + "urlregexpnumber.value = index;\n" + "  " + seqPrefix + "SpecOp(\"" + seqPrefix + "urlregexpop\",\"Delete\",anchorvalue);\n" + "}\n" + "\n" + "function " + seqPrefix + "URLRegexpAdd(anchorvalue)\n" + "{\n" + "  " + seqPrefix + "SpecOp(\"" + seqPrefix + "urlregexpop\",\"Add\",anchorvalue);\n" + "}\n" + "\n" + "function " + seqPrefix + "checkSpecification()\n" + "{\n" + "  if (editjob." + seqPrefix + "feedtimeout.value == \"\" || !isInteger(editjob." + seqPrefix + "feedtimeout.value))\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.ATimeoutValueInSecondsIsRequired") + "\");\n" + "    editjob." + seqPrefix + "feedtimeout.focus();\n" + "    return false;\n" + "  }\n" + "  if (editjob." + seqPrefix + "feedrefetch.value == \"\" || !isInteger(editjob." + seqPrefix + "feedrefetch.value))\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.ARefetchIntervalInMinutesIsRequired") + "\");\n" + "    editjob." + seqPrefix + "feedrefetch.focus();\n" + "    return false;\n" + "  }\n" + "  if (editjob." + seqPrefix + "minfeedrefetch.value == \"\" || !isInteger(editjob." + seqPrefix + "minfeedrefetch.value))\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.AMinimumRefetchIntervalInMinutesIsRequire") + "\");\n" + "    editjob." + seqPrefix + "minfeedrefetch.focus();\n" + "    return false;\n" + "  }\n" + "  if (editjob." + seqPrefix + "badfeedrefetch.value != \"\" && !isInteger(editjob." + seqPrefix + "badfeedrefetch.value))\n" + "  {\n" + "    alert(\"" + Messages.getBodyJavascriptString(locale, "RSSConnector.ABadFeedRefetchIntervalInMinutesIsRequired") + "\");\n" + "    editjob." + seqPrefix + "badfeedrefetch.focus();\n" + "    return false;\n" + "  }\n" + "\n" + "  return true;\n" + "}\n" + "\n" + "//-->\n" + "</script>\n");
    }

    /**
     *  Output the specification body section.
     *  This method is called in the body section of a job page which has selected a repository connection of the
     *  current type.  Its purpose is to present the required form elements for editing.
     *  The coder can presume that the HTML that is output from this configuration will be within appropriate
     *   &lt;html&gt;, &lt;body&gt;, and &lt;form&gt; tags.  The name of the form is always "editjob".
     *  The connector will be connected before this method can be called.
     * @param out is the output to which any HTML should be sent.
     * @param locale is the locale the output is preferred to be in.
     * @param ds is the current document specification for this job.
     * @param connectionSequenceNumber is the unique number of this connection within the job.
     * @param actualSequenceNumber is the connection within the job that has currently been selected.
     * @param tabName is the current tab name.  (actualSequenceNumber, tabName) form a unique tuple within
     *   the job.
     */
    @Override
    public void outputSpecificationBody(IHTTPOutput out, Locale locale, Specification ds, int connectionSequenceNumber, int actualSequenceNumber, String tabName) throws ManifoldCFException, IOException {
        String seqPrefix = "s" + connectionSequenceNumber + "_";
        int i;
        int k;
        // Build the url seed string, and the url regexp match and map
        StringBuilder sb = new StringBuilder();
        ArrayList regexp = new ArrayList();
        ArrayList matchStrings = new ArrayList();
        int feedTimeoutValue = 60;
        int feedRefetchValue = 60;
        int minFeedRefetchValue = 15;
        Integer badFeedRefetchValue = null;
        String exclusions = "";
        // Now, loop through paths
        i = 0;
        while (i < ds.getChildCount()) {
            SpecificationNode sn = ds.getChild(i++);
            if (sn.getType().equals(RSSConfig.NODE_FEED)) {
                String rssURL = sn.getAttributeValue(RSSConfig.ATTR_URL);
                if (rssURL != null) {
                    sb.append(rssURL).append("\n");
                }
            } else if (sn.getType().equals(RSSConfig.NODE_EXCLUDES)) {
                exclusions = sn.getValue();
                if (exclusions == null)
                    exclusions = "";
            } else if (sn.getType().equals(RSSConfig.NODE_MAP)) {
                String match = sn.getAttributeValue(RSSConfig.ATTR_MATCH);
                String map = sn.getAttributeValue(RSSConfig.ATTR_MAP);
                if (match != null) {
                    regexp.add(match);
                    if (map == null)
                        map = "";
                    matchStrings.add(map);
                }
            } else if (sn.getType().equals(RSSConfig.NODE_FEEDTIMEOUT)) {
                String value = sn.getAttributeValue(RSSConfig.ATTR_VALUE);
                feedTimeoutValue = Integer.parseInt(value);
            } else if (sn.getType().equals(RSSConfig.NODE_FEEDRESCAN)) {
                String value = sn.getAttributeValue(RSSConfig.ATTR_VALUE);
                feedRefetchValue = Integer.parseInt(value);
            } else if (sn.getType().equals(RSSConfig.NODE_MINFEEDRESCAN)) {
                String value = sn.getAttributeValue(RSSConfig.ATTR_VALUE);
                minFeedRefetchValue = Integer.parseInt(value);
            } else if (sn.getType().equals(RSSConfig.NODE_BADFEEDRESCAN)) {
                String value = sn.getAttributeValue(RSSConfig.ATTR_VALUE);
                badFeedRefetchValue = new Integer(value);
            }
        }
        // URLs tab
        if (tabName.equals(Messages.getString(locale, "RSSConnector.URLs")) && connectionSequenceNumber == actualSequenceNumber) {
            out.print("<table class=\"displaytable\">\n" + "  <tr><td class=\"separator\" colspan=\"2\"><hr/></td></tr>\n" + "  <tr>\n" + "    <td class=\"value\" colspan=\"2\">\n" + "      <textarea rows=\"25\" cols=\"80\" name=\"" + seqPrefix + "rssurls\">" + org.apache.manifoldcf.ui.util.Encoder.bodyEscape(sb.toString()) + "</textarea>\n" + "    </td>\n" + "  </tr>\n" + "</table>\n");
        } else {
            out.print("<input type=\"hidden\" name=\"" + seqPrefix + "rssurls\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(sb.toString()) + "\"/>\n");
        }
        // Exclusions tab
        if (tabName.equals(Messages.getString(locale, "RSSConnector.Exclusions")) && connectionSequenceNumber == actualSequenceNumber) {
            out.print("<table class=\"displaytable\">\n" + "  <tr><td class=\"separator\" colspan=\"2\"><hr/></td></tr>\n" + "  <tr>\n" + "    <td class=\"description\" colspan=\"1\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.Exclude") + "</nobr></td>\n" + "    <td class=\"value\" colspan=\"1\">\n" + "      <textarea rows=\"25\" cols=\"60\" name=\"" + seqPrefix + "exclusions\">" + org.apache.manifoldcf.ui.util.Encoder.bodyEscape(exclusions) + "</textarea>\n" + "    </td>\n" + "  </tr>\n" + "</table>\n");
        } else {
            out.print("<input type=\"hidden\" name=\"" + seqPrefix + "exclusions\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(exclusions) + "\"/>\n");
        }
        // Canonicalization tab
        if (tabName.equals(Messages.getString(locale, "RSSConnector.Canonicalization")) && connectionSequenceNumber == actualSequenceNumber) {
            out.print("<table class=\"displaytable\">\n" + "  <tr><td class=\"separator\" colspan=\"2\"><hr/></td></tr>\n" + "  <tr>\n" + "    <td class=\"boxcell\" colspan=\"2\">\n" + "      <input type=\"hidden\" name=\"" + seqPrefix + "urlregexpop\" value=\"Continue\"/>\n" + "      <input type=\"hidden\" name=\"" + seqPrefix + "urlregexpnumber\" value=\"\"/>\n" + "      <table class=\"formtable\">\n" + "        <tr class=\"formheaderrow\">\n" + "          <td class=\"formcolumnheader\"></td>\n" + "          <td class=\"formcolumnheader\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.URLRegularExpression") + "</nobr></td>\n" + "          <td class=\"formcolumnheader\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.Description") + "</nobr></td>\n" + "          <td class=\"formcolumnheader\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.Reorder") + "</nobr></td>\n" + "          <td class=\"formcolumnheader\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.RemoveJSPSessions") + "</nobr></td>\n" + "          <td class=\"formcolumnheader\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.RemoveASPSessions") + "</nobr></td>\n" + "          <td class=\"formcolumnheader\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.RemovePHPSessions") + "</nobr></td>\n" + "          <td class=\"formcolumnheader\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.RemoveBVSessions") + "</nobr></td>\n" + "        </tr>\n");
            int q = 0;
            int l = 0;
            while (q < ds.getChildCount()) {
                SpecificationNode specNode = ds.getChild(q++);
                if (specNode.getType().equals(RSSConfig.NODE_URLSPEC)) {
                    // Ok, this node matters to us
                    String regexpString = specNode.getAttributeValue(RSSConfig.ATTR_REGEXP);
                    String description = specNode.getAttributeValue(RSSConfig.ATTR_DESCRIPTION);
                    if (description == null)
                        description = "";
                    String allowReorder = specNode.getAttributeValue(RSSConfig.ATTR_REORDER);
                    if (allowReorder == null || allowReorder.length() == 0)
                        allowReorder = RSSConfig.VALUE_NO;
                    String allowJavaSessionRemoval = specNode.getAttributeValue(RSSConfig.ATTR_JAVASESSIONREMOVAL);
                    if (allowJavaSessionRemoval == null || allowJavaSessionRemoval.length() == 0)
                        allowJavaSessionRemoval = RSSConfig.VALUE_NO;
                    String allowASPSessionRemoval = specNode.getAttributeValue(RSSConfig.ATTR_ASPSESSIONREMOVAL);
                    if (allowASPSessionRemoval == null || allowASPSessionRemoval.length() == 0)
                        allowASPSessionRemoval = RSSConfig.VALUE_NO;
                    String allowPHPSessionRemoval = specNode.getAttributeValue(RSSConfig.ATTR_PHPSESSIONREMOVAL);
                    if (allowPHPSessionRemoval == null || allowPHPSessionRemoval.length() == 0)
                        allowPHPSessionRemoval = RSSConfig.VALUE_NO;
                    String allowBVSessionRemoval = specNode.getAttributeValue(RSSConfig.ATTR_BVSESSIONREMOVAL);
                    if (allowBVSessionRemoval == null || allowBVSessionRemoval.length() == 0)
                        allowBVSessionRemoval = RSSConfig.VALUE_NO;
                    out.print("        <tr class=\"" + (((l % 2) == 0) ? "evenformrow" : "oddformrow") + "\">\n" + "          <td class=\"formcolumncell\">\n" + "            <a name=\"" + seqPrefix + "urlregexp_" + Integer.toString(l) + "\">\n" + "              <input type=\"button\" value=\"Delete\" alt=\"" + Messages.getAttributeString(locale, "RSSConnector.DeleteUrlRegexp") + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(regexpString) + "\" onclick='javascript:" + seqPrefix + "URLRegexpDelete(" + Integer.toString(l) + ",\"" + seqPrefix + "urlregexp_" + Integer.toString(l) + "\");'/>\n" + "            </a>\n" + "          </td>\n" + "          <td class=\"formcolumncell\">\n" + "            <input type=\"hidden\" name=\"" + seqPrefix + "urlregexp_" + Integer.toString(l) + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(regexpString) + "\"/>\n" + "            <input type=\"hidden\" name=\"" + seqPrefix + "urlregexpdesc_" + Integer.toString(l) + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(description) + "\"/>\n" + "            <input type=\"hidden\" name=\"" + seqPrefix + "urlregexpreorder_" + Integer.toString(l) + "\" value=\"" + allowReorder + "\"/>\n" + "            <input type=\"hidden\" name=\"" + seqPrefix + "urlregexpjava_" + Integer.toString(l) + "\" value=\"" + allowJavaSessionRemoval + "\"/>\n" + "            <input type=\"hidden\" name=\"" + seqPrefix + "urlregexpasp_" + Integer.toString(l) + "\" value=\"" + allowASPSessionRemoval + "\"/>\n" + "            <input type=\"hidden\" name=\"" + seqPrefix + "urlregexpphp_" + Integer.toString(l) + "\" value=\"" + allowPHPSessionRemoval + "\"/>\n" + "            <input type=\"hidden\" name=\"" + seqPrefix + "urlregexpbv_" + Integer.toString(l) + "\" value=\"" + allowBVSessionRemoval + "\"/>\n" + "            <nobr>" + org.apache.manifoldcf.ui.util.Encoder.bodyEscape(regexpString) + "</nobr>\n" + "          </td>\n" + "          <td class=\"formcolumncell\">" + org.apache.manifoldcf.ui.util.Encoder.bodyEscape(description) + "</td>\n" + "          <td class=\"formcolumncell\">" + allowReorder + "</td>\n" + "          <td class=\"formcolumncell\">" + allowJavaSessionRemoval + "</td>\n" + "          <td class=\"formcolumncell\">" + allowASPSessionRemoval + "</td>\n" + "          <td class=\"formcolumncell\">" + allowPHPSessionRemoval + "</td>\n" + "          <td class=\"formcolumncell\">" + allowBVSessionRemoval + "</td>\n" + "        </tr>\n");
                    l++;
                }
            }
            if (l == 0) {
                out.print("        <tr class=\"formrow\"><td colspan=\"8\" class=\"formcolumnmessage\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.NoCanonicalizationSpecified") + "</nobr></td></tr>\n");
            }
            out.print("        <tr class=\"formrow\"><td colspan=\"8\" class=\"formseparator\"><hr/></td></tr>\n" + "        <tr class=\"formrow\">\n" + "          <td class=\"formcolumncell\">\n" + "            <a name=\"" + seqPrefix + "urlregexp_" + Integer.toString(l) + "\">\n" + "              <input type=\"button\" value=\"Add\" alt=\"" + Messages.getAttributeString(locale, "RSSConnector.AddUlRegexp") + "\" onclick='javascript:" + seqPrefix + "URLRegexpAdd(\"" + seqPrefix + "urlregexp_" + Integer.toString(l + 1) + "\");'/>\n" + "              <input type=\"hidden\" name=\"" + seqPrefix + "urlregexpcount\" value=\"" + Integer.toString(l) + "\"/>\n" + "            </a>\n" + "          </td>\n" + "          <td class=\"formcolumncell\"><input type=\"text\" name=\"" + seqPrefix + "urlregexp\" size=\"30\" value=\"\"/></td>\n" + "          <td class=\"formcolumncell\"><input type=\"text\" name=\"" + seqPrefix + "urlregexpdesc\" size=\"30\" value=\"\"/></td>\n" + "          <td class=\"formcolumncell\"><input type=\"checkbox\" name=\"" + seqPrefix + "urlregexpreorder\" value=\"yes\"/></td>\n" + "          <td class=\"formcolumncell\"><input type=\"checkbox\" name=\"" + seqPrefix + "urlregexpjava\" value=\"yes\" checked=\"true\"/></td>\n" + "          <td class=\"formcolumncell\"><input type=\"checkbox\" name=\"" + seqPrefix + "urlregexpasp\" value=\"yes\" checked=\"true\"/></td>\n" + "          <td class=\"formcolumncell\"><input type=\"checkbox\" name=\"" + seqPrefix + "urlregexpphp\" value=\"yes\" checked=\"true\"/></td>\n" + "          <td class=\"formcolumncell\"><input type=\"checkbox\" name=\"" + seqPrefix + "urlregexpbv\" value=\"yes\" checked=\"true\"/></td>\n" + "        </tr>\n" + "      </table>\n" + "    </td>\n" + "  </tr>\n" + "</table>\n");
        } else {
            // Post the canonicalization specification
            int q = 0;
            int l = 0;
            while (q < ds.getChildCount()) {
                SpecificationNode specNode = ds.getChild(q++);
                if (specNode.getType().equals(RSSConfig.NODE_URLSPEC)) {
                    // Ok, this node matters to us
                    String regexpString = specNode.getAttributeValue(RSSConfig.ATTR_REGEXP);
                    String description = specNode.getAttributeValue(RSSConfig.ATTR_DESCRIPTION);
                    if (description == null)
                        description = "";
                    String allowReorder = specNode.getAttributeValue(RSSConfig.ATTR_REORDER);
                    if (allowReorder == null || allowReorder.length() == 0)
                        allowReorder = RSSConfig.VALUE_NO;
                    String allowJavaSessionRemoval = specNode.getAttributeValue(RSSConfig.ATTR_JAVASESSIONREMOVAL);
                    if (allowJavaSessionRemoval == null || allowJavaSessionRemoval.length() == 0)
                        allowJavaSessionRemoval = RSSConfig.VALUE_NO;
                    String allowASPSessionRemoval = specNode.getAttributeValue(RSSConfig.ATTR_ASPSESSIONREMOVAL);
                    if (allowASPSessionRemoval == null || allowASPSessionRemoval.length() == 0)
                        allowASPSessionRemoval = RSSConfig.VALUE_NO;
                    String allowPHPSessionRemoval = specNode.getAttributeValue(RSSConfig.ATTR_PHPSESSIONREMOVAL);
                    if (allowPHPSessionRemoval == null || allowPHPSessionRemoval.length() == 0)
                        allowPHPSessionRemoval = RSSConfig.VALUE_NO;
                    String allowBVSessionRemoval = specNode.getAttributeValue(RSSConfig.ATTR_BVSESSIONREMOVAL);
                    if (allowBVSessionRemoval == null || allowBVSessionRemoval.length() == 0)
                        allowBVSessionRemoval = RSSConfig.VALUE_NO;
                    out.print("<input type=\"hidden\" name=\"" + seqPrefix + "urlregexp_" + Integer.toString(l) + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(regexpString) + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "urlregexpdesc_" + Integer.toString(l) + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(description) + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "urlregexpreorder_" + Integer.toString(l) + "\" value=\"" + allowReorder + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "urlregexpjava_" + Integer.toString(l) + "\" value=\"" + allowJavaSessionRemoval + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "urlregexpasp_" + Integer.toString(l) + "\" value=\"" + allowASPSessionRemoval + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "urlregexpphp_" + Integer.toString(l) + "\" value=\"" + allowPHPSessionRemoval + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "urlregexpbv_" + Integer.toString(l) + "\" value=\"" + allowBVSessionRemoval + "\"/>\n");
                    l++;
                }
            }
            out.print("<input type=\"hidden\" name=\"" + seqPrefix + "urlregexpcount\" value=\"" + Integer.toString(l) + "\"/>\n");
        }
        // Mappings tab
        if (tabName.equals(Messages.getString(locale, "RSSConnector.URLMappings")) && connectionSequenceNumber == actualSequenceNumber) {
            out.print("<input type=\"hidden\" name=\"" + seqPrefix + "rssop\" value=\"\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "rssindex\" value=\"\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "rssmapcount\" value=\"" + Integer.toString(regexp.size()) + "\"/>\n" + "\n" + "<table class=\"displaytable\">\n" + "  <tr><td class=\"separator\" colspan=\"4\"><hr/></td></tr>\n");
            i = 0;
            while (i < regexp.size()) {
                String prefix = seqPrefix + "rssregexp_" + Integer.toString(i) + "_";
                out.print("  <tr>\n" + "    <td class=\"value\">\n" + "      <a name=\"" + seqPrefix + "regexp_" + Integer.toString(i) + "\">\n" + "        <input type=\"button\" value=\"" + Messages.getAttributeString(locale, "RSSConnector.Remove") + "\" onclick='javascript:" + seqPrefix + "RemoveRegexp(" + Integer.toString(i) + ",\"" + seqPrefix + "regexp_" + Integer.toString(i) + "\")' alt=\"" + Messages.getAttributeString(locale, "RSSConnector.RemoveRegexp") + Integer.toString(i) + "\"/>\n" + "      </a>\n" + "    </td>\n" + "    <td class=\"value\"><input type=\"hidden\" name=\"" + prefix + "match" + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape((String) regexp.get(i)) + "\"/>" + org.apache.manifoldcf.ui.util.Encoder.bodyEscape((String) regexp.get(i)) + "</td>\n" + "    <td class=\"value\">--&gt;</td>\n" + "    <td class=\"value\">\n");
                String match = (String) matchStrings.get(i);
                out.print("      <input type=\"hidden\" name=\"" + prefix + "map" + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(match) + "\"/>\n");
                if (match.length() == 0) {
                    out.print("      &lt;as is&gt;\n");
                } else {
                    out.print("      " + org.apache.manifoldcf.ui.util.Encoder.bodyEscape(match) + "\n");
                }
                out.print("    </td>\n" + "  </tr>\n");
                i++;
            }
            out.print("  <tr>\n" + "    <td class=\"value\"><a name=\"" + seqPrefix + "regexp_" + Integer.toString(i) + "\"><input type=\"button\" value=\"" + Messages.getAttributeString(locale, "RSSConnector.Add") + "\" onclick='javascript:" + seqPrefix + "AddRegexp(\"" + seqPrefix + "regexp_" + Integer.toString(i + 1) + "\")' alt=\"" + Messages.getAttributeString(locale, "RSSConnector.AddRegexp") + "\"/></a></td>\n" + "    <td class=\"value\"><input type=\"text\" name=\"" + seqPrefix + "rssmatch\" size=\"16\" value=\"\"/></td>\n" + "    <td class=\"value\">--&gt;</td>\n" + "    <td class=\"value\"><input type=\"text\" name=\"" + seqPrefix + "rssmap\" size=\"16\" value=\"\"/></td>\n" + "  </tr>\n" + "</table>\n");
        } else {
            out.print("<input type=\"hidden\" name=\"" + seqPrefix + "rssmapcount\" value=\"" + Integer.toString(regexp.size()) + "\"/>\n");
            i = 0;
            while (i < regexp.size()) {
                String prefix = seqPrefix + "rssregexp_" + Integer.toString(i) + "_";
                String match = (String) matchStrings.get(i);
                out.print("<input type=\"hidden\" name=\"" + prefix + "match" + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape((String) regexp.get(i)) + "\"/>\n" + "<input type=\"hidden\" name=\"" + prefix + "map" + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(match) + "\"/>\n");
                i++;
            }
        }
        // Timeout Value tab
        if (tabName.equals(Messages.getString(locale, "RSSConnector.TimeValues")) && connectionSequenceNumber == actualSequenceNumber) {
            out.print("<table class=\"displaytable\">\n" + "  <tr><td class=\"separator\" colspan=\"2\"><hr/></td></tr>\n" + "  <tr>\n" + "    <td class=\"description\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.FeedConnectTimeout") + "</nobr></td>\n" + "    <td class=\"value\"><input type=\"text\" size=\"5\" name=\"" + seqPrefix + "feedtimeout\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(Integer.toString(feedTimeoutValue)) + "\"/></td>\n" + "  </tr>\n" + "  <tr>\n" + "    <td class=\"description\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.DefaultFeedRefetchTime") + "</nobr></td>\n" + "    <td class=\"value\"><input type=\"text\" size=\"5\" name=\"" + seqPrefix + "feedrefetch\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(Integer.toString(feedRefetchValue)) + "\"/></td>\n" + "  </tr>\n" + "  <tr>\n" + "    <td class=\"description\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.MinimumFeedRefetchTime") + "</nobr></td>\n" + "    <td class=\"value\"><input type=\"text\" size=\"5\" name=\"" + seqPrefix + "minfeedrefetch\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(Integer.toString(minFeedRefetchValue)) + "\"/></td>\n" + "  </tr>\n" + "  <tr>\n" + "    <td class=\"description\"><nobr>" + Messages.getBodyString(locale, "RSSConnector.BadFeedRefetchTime") + "</nobr></td>\n" + "    <td class=\"value\">\n" + "      <input type=\"hidden\" name=\"" + seqPrefix + "badfeedrefetch_present\" value=\"true\"/>\n" + "      <input type=\"text\" size=\"5\" name=\"" + seqPrefix + "badfeedrefetch\" value=\"" + ((badFeedRefetchValue == null) ? "" : org.apache.manifoldcf.ui.util.Encoder.attributeEscape(badFeedRefetchValue.toString())) + "\"/>\n" + "    </td>\n" + "  </tr>\n" + "\n" + "</table>\n");
        } else {
            out.print("<input type=\"hidden\" name=\"" + seqPrefix + "feedtimeout\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(Integer.toString(feedTimeoutValue)) + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "feedrefetch\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(Integer.toString(feedRefetchValue)) + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "minfeedrefetch\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(Integer.toString(minFeedRefetchValue)) + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "badfeedrefetch_present\" value=\"true\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "badfeedrefetch\" value=\"" + ((badFeedRefetchValue == null) ? "" : org.apache.manifoldcf.ui.util.Encoder.attributeEscape(badFeedRefetchValue.toString())) + "\"/>\n");
        }
        // Dechromed content tab
        String dechromedMode = RSSConfig.VALUE_NONE;
        String chromedMode = RSSConfig.VALUE_USE;
        i = 0;
        while (i < ds.getChildCount()) {
            SpecificationNode sn = ds.getChild(i++);
            if (sn.getType().equals(RSSConfig.NODE_DECHROMEDMODE))
                dechromedMode = sn.getAttributeValue(RSSConfig.ATTR_MODE);
            else if (sn.getType().equals(RSSConfig.NODE_CHROMEDMODE))
                chromedMode = sn.getAttributeValue(RSSConfig.ATTR_MODE);
        }
        if (tabName.equals(Messages.getString(locale, "RSSConnector.DechromedContent")) && connectionSequenceNumber == actualSequenceNumber) {
            out.print("<table class=\"displaytable\">\n" + "  <tr><td class=\"separator\" colspan=\"1\"><hr/></td></tr>\n" + "  <tr>\n" + "    <td class=\"value\"><nobr><input type=\"radio\" name=\"" + seqPrefix + "dechromedmode\" value=\"none\" " + (dechromedMode.equals(RSSConfig.VALUE_NONE) ? "checked=\"true\"" : "") + "/>" + Messages.getBodyString(locale, "RSSConnector.NoDechromedContent") + "</nobr></td>\n" + "  </tr>\n" + "  <tr>\n" + "    <td class=\"value\"><nobr><input type=\"radio\" name=\"" + seqPrefix + "dechromedmode\" value=\"description\" " + (dechromedMode.equals(RSSConfig.VALUE_DESCRIPTION) ? "checked=\"true\"" : "") + "/>" + Messages.getBodyString(locale, "RSSConnector.DechromedContentIfPresentInDescriptionField") + "</nobr></td>\n" + "  </tr>\n" + "  <tr>\n" + "    <td class=\"value\"><nobr><input type=\"radio\" name=\"" + seqPrefix + "dechromedmode\" value=\"content\" " + (dechromedMode.equals(RSSConfig.VALUE_CONTENT) ? "checked=\"true\"" : "") + "/>" + Messages.getBodyString(locale, "RSSConnector.DechromedContentIfPresentInContentField") + "</nobr></td>\n" + "  </tr>\n" + "  <tr>\n" + "    <td class=\"separator\"><hr/></td>\n" + "  </tr>\n" + "  <tr>\n" + "    <td class=\"value\"><nobr><input type=\"radio\" name=\"" + seqPrefix + "chromedmode\" value=\"use\" " + (chromedMode.equals(RSSConfig.VALUE_USE) ? "checked=\"true\"" : "") + "/>" + Messages.getBodyString(locale, "RSSConnector.UseChromedContentIfNoDechromedContentFound") + "</nobr></td>\n" + "  </tr>\n" + "  <tr>\n" + "    <td class=\"value\"><nobr><input type=\"radio\" name=\"" + seqPrefix + "chromedmode\" value=\"skip\" " + (chromedMode.equals(RSSConfig.VALUE_SKIP) ? "checked=\"true\"" : "") + "/>" + Messages.getBodyString(locale, "RSSConnector.NeverUseChromedContent") + "</nobr></td>\n" + "  </tr>\n" + "  <tr>\n" + "    <td class=\"value\"><nobr><input type=\"radio\" name=\"" + seqPrefix + "chromedmode\" value=\"metadata\" " + (chromedMode.equals(RSSConfig.VALUE_METADATA) ? "checked=\"true\"" : "") + "/>" + Messages.getBodyString(locale, "RSSConnector.NoContentMetadataOnly") + "</nobr></td>\n" + "  </tr>\n" + "</table>\n");
        } else {
            out.print("<input type=\"hidden\" name=\"" + seqPrefix + "dechromedmode\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(dechromedMode) + "\"/>\n" + "<input type=\"hidden\" name=\"" + seqPrefix + "chromedmode\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(chromedMode) + "\"/>\n");
        }
        // Security tab
        // There is no native security, so all we care about are the tokens.
        i = 0;
        if (tabName.equals(Messages.getString(locale, "RSSConnector.Security")) && connectionSequenceNumber == actualSequenceNumber) {
            out.print("<table class=\"displaytable\">\n" + "  <tr><td class=\"separator\" colspan=\"2\"><hr/></td></tr>\n");
            // Go through forced ACL
            i = 0;
            k = 0;
            while (i < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(i++);
                if (sn.getType().equals(RSSConfig.NODE_ACCESS)) {
                    String accessDescription = "_" + Integer.toString(k);
                    String accessOpName = seqPrefix + "accessop" + accessDescription;
                    String token = sn.getAttributeValue(RSSConfig.ATTR_TOKEN);
                    out.print("  <tr>\n" + "    <td class=\"description\">\n" + "      <input type=\"hidden\" name=\"" + accessOpName + "\" value=\"\"/>\n" + "      <input type=\"hidden\" name=\"" + seqPrefix + "spectoken" + accessDescription + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(token) + "\"/>\n" + "      <a name=\"" + seqPrefix + "token_" + Integer.toString(k) + "\">\n" + "        <input type=\"button\" value=\"Delete\" onClick='Javascript:" + seqPrefix + "SpecOp(\"" + accessOpName + "\",\"Delete\",\"" + seqPrefix + "token_" + Integer.toString(k) + "\")' alt=\"" + Messages.getAttributeString(locale, "RSSConnector.DeleteToken") + Integer.toString(k) + "\"/>\n" + "      </a>&nbsp;\n" + "    </td>\n" + "    <td class=\"value\">\n" + "      " + org.apache.manifoldcf.ui.util.Encoder.bodyEscape(token) + "\n" + "    </td>\n" + "  </tr>\n");
                    k++;
                }
            }
            if (k == 0) {
                out.print("  <tr>\n" + "    <td class=\"message\" colspan=\"2\">" + Messages.getBodyString(locale, "RSSConnector.NoAccessTokensPresent") + "</td>\n" + "  </tr>\n");
            }
            out.print("  <tr><td class=\"lightseparator\" colspan=\"2\"><hr/></td></tr>\n" + "  <tr>\n" + "    <td class=\"description\">\n" + "      <input type=\"hidden\" name=\"" + seqPrefix + "tokencount\" value=\"" + Integer.toString(k) + "\"/>\n" + "      <input type=\"hidden\" name=\"" + seqPrefix + "accessop\" value=\"\"/>\n" + "      <a name=\"" + seqPrefix + "token_" + Integer.toString(k) + "\">\n" + "        <input type=\"button\" value=\"Add\" onClick='Javascript:" + seqPrefix + "SpecAddToken(\"" + seqPrefix + "token_" + Integer.toString(k + 1) + "\")' alt=\"" + Messages.getAttributeString(locale, "RSSConnector.AddAccessToken") + "\"/>\n" + "      </a>&nbsp;\n" + "    </td>\n" + "    <td class=\"value\">\n" + "      <input type=\"text\" size=\"30\" name=\"" + seqPrefix + "spectoken\" value=\"\"/>\n" + "    </td>\n" + "  </tr>\n" + "</table>\n");
        } else {
            // Finally, go through forced ACL
            i = 0;
            k = 0;
            while (i < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(i++);
                if (sn.getType().equals(RSSConfig.NODE_ACCESS)) {
                    String accessDescription = "_" + Integer.toString(k);
                    String token = sn.getAttributeValue(RSSConfig.ATTR_TOKEN);
                    out.print("<input type=\"hidden\" name=\"" + seqPrefix + "spectoken" + accessDescription + "\" value=\"" + org.apache.manifoldcf.ui.util.Encoder.attributeEscape(token) + "\"/>\n");
                    k++;
                }
            }
            out.print("<input type=\"hidden\" name=\"" + seqPrefix + "tokencount\" value=\"" + Integer.toString(k) + "\"/>\n");
        }
    }

    /**
     *  Process a specification post.
     *  This method is called at the start of job's edit or view page, whenever there is a possibility that form
     *  data for a connection has been posted.  Its purpose is to gather form information and modify the
     *  document specification accordingly.  The name of the posted form is always "editjob".
     *  The connector will be connected before this method can be called.
     * @param variableContext contains the post data, including binary file-upload information.
     * @param locale is the locale the output is preferred to be in.
     * @param ds is the current document specification for this job.
     * @param connectionSequenceNumber is the unique number of this connection within the job.
     * @return null if all is well, or a string error message if there is an error that should prevent saving of
     *  the job (and cause a redirection to an error page).
     */
    @Override
    public String processSpecificationPost(IPostParameters variableContext, Locale locale, Specification ds, int connectionSequenceNumber) throws ManifoldCFException {
        String seqPrefix = "s" + connectionSequenceNumber + "_";
        // Get the map
        String value = variableContext.getParameter(seqPrefix + "rssmapcount");
        if (value != null) {
            int mapsize = Integer.parseInt(value);
            // Clear it first
            int j = 0;
            while (j < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(j);
                if (sn.getType().equals(RSSConfig.NODE_MAP))
                    ds.removeChild(j);
                else
                    j++;
            }
            // Grab the map values
            j = 0;
            while (j < mapsize) {
                String prefix = seqPrefix + "rssregexp_" + Integer.toString(j) + "_";
                String match = variableContext.getParameter(prefix + "match");
                String map = variableContext.getParameter(prefix + "map");
                if (map == null)
                    map = "";
                // Add to the documentum specification
                SpecificationNode node = new SpecificationNode(RSSConfig.NODE_MAP);
                node.setAttribute(RSSConfig.ATTR_MATCH, match);
                node.setAttribute(RSSConfig.ATTR_MAP, map);
                ds.addChild(ds.getChildCount(), node);
                j++;
            }
        }
        // Get the cgiPath
        String rssURLSequence = variableContext.getParameter(seqPrefix + "rssurls");
        if (rssURLSequence != null) {
            // Delete all url specs first
            int i = 0;
            while (i < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(i);
                if (sn.getType().equals(RSSConfig.NODE_FEED))
                    ds.removeChild(i);
                else
                    i++;
            }
            try {
                java.io.Reader str = new java.io.StringReader(rssURLSequence);
                try {
                    java.io.BufferedReader is = new java.io.BufferedReader(str);
                    try {
                        while (true) {
                            String nextString = is.readLine();
                            if (nextString == null)
                                break;
                            if (nextString.length() == 0)
                                continue;
                            SpecificationNode node = new SpecificationNode(RSSConfig.NODE_FEED);
                            node.setAttribute(RSSConfig.ATTR_URL, nextString);
                            ds.addChild(ds.getChildCount(), node);
                        }
                    } finally {
                        is.close();
                    }
                } finally {
                    str.close();
                }
            } catch (java.io.IOException e) {
                throw new ManifoldCFException("IO error: " + e.getMessage(), e);
            }
        }
        // Read the url specs
        String urlRegexpCount = variableContext.getParameter(seqPrefix + "urlregexpcount");
        if (urlRegexpCount != null && urlRegexpCount.length() > 0) {
            int regexpCount = Integer.parseInt(urlRegexpCount);
            int j = 0;
            while (j < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(j);
                if (sn.getType().equals(RSSConfig.NODE_URLSPEC))
                    ds.removeChild(j);
                else
                    j++;
            }
            // Grab the operation and the index (if any)
            String operation = variableContext.getParameter(seqPrefix + "urlregexpop");
            if (operation == null)
                operation = "Continue";
            int opIndex = -1;
            if (operation.equals("Delete"))
                opIndex = Integer.parseInt(variableContext.getParameter(seqPrefix + "urlregexpnumber"));
            // Reconstruct urlspec nodes
            j = 0;
            while (j < regexpCount) {
                // For each index, first look for a delete operation
                if (!operation.equals("Delete") || j != opIndex) {
                    // Add the jth node
                    String regexp = variableContext.getParameter(seqPrefix + "urlregexp_" + Integer.toString(j));
                    String regexpDescription = variableContext.getParameter(seqPrefix + "urlregexpdesc_" + Integer.toString(j));
                    String reorder = variableContext.getParameter(seqPrefix + "urlregexpreorder_" + Integer.toString(j));
                    String javaSession = variableContext.getParameter(seqPrefix + "urlregexpjava_" + Integer.toString(j));
                    String aspSession = variableContext.getParameter(seqPrefix + "urlregexpasp_" + Integer.toString(j));
                    String phpSession = variableContext.getParameter(seqPrefix + "urlregexpphp_" + Integer.toString(j));
                    String bvSession = variableContext.getParameter(seqPrefix + "urlregexpbv_" + Integer.toString(j));
                    SpecificationNode newSn = new SpecificationNode(RSSConfig.NODE_URLSPEC);
                    newSn.setAttribute(RSSConfig.ATTR_REGEXP, regexp);
                    if (regexpDescription != null && regexpDescription.length() > 0)
                        newSn.setAttribute(RSSConfig.VALUE_DESCRIPTION, regexpDescription);
                    if (reorder != null && reorder.length() > 0)
                        newSn.setAttribute(RSSConfig.ATTR_REORDER, reorder);
                    if (javaSession != null && javaSession.length() > 0)
                        newSn.setAttribute(RSSConfig.ATTR_JAVASESSIONREMOVAL, javaSession);
                    if (aspSession != null && aspSession.length() > 0)
                        newSn.setAttribute(RSSConfig.ATTR_ASPSESSIONREMOVAL, aspSession);
                    if (phpSession != null && phpSession.length() > 0)
                        newSn.setAttribute(RSSConfig.ATTR_PHPSESSIONREMOVAL, phpSession);
                    if (bvSession != null && bvSession.length() > 0)
                        newSn.setAttribute(RSSConfig.ATTR_BVSESSIONREMOVAL, bvSession);
                    ds.addChild(ds.getChildCount(), newSn);
                }
                j++;
            }
            if (operation.equals("Add")) {
                String regexp = variableContext.getParameter(seqPrefix + "urlregexp");
                String regexpDescription = variableContext.getParameter(seqPrefix + "urlregexpdesc");
                String reorder = variableContext.getParameter(seqPrefix + "urlregexpreorder");
                String javaSession = variableContext.getParameter(seqPrefix + "urlregexpjava");
                String aspSession = variableContext.getParameter(seqPrefix + "urlregexpasp");
                String phpSession = variableContext.getParameter(seqPrefix + "urlregexpphp");
                String bvSession = variableContext.getParameter(seqPrefix + "urlregexpbv");
                // Add a new node at the end
                SpecificationNode newSn = new SpecificationNode(RSSConfig.NODE_URLSPEC);
                newSn.setAttribute(RSSConfig.ATTR_REGEXP, regexp);
                if (regexpDescription != null && regexpDescription.length() > 0)
                    newSn.setAttribute(RSSConfig.VALUE_DESCRIPTION, regexpDescription);
                if (reorder != null && reorder.length() > 0)
                    newSn.setAttribute(RSSConfig.ATTR_REORDER, reorder);
                if (javaSession != null && javaSession.length() > 0)
                    newSn.setAttribute(RSSConfig.ATTR_JAVASESSIONREMOVAL, javaSession);
                if (aspSession != null && aspSession.length() > 0)
                    newSn.setAttribute(RSSConfig.ATTR_ASPSESSIONREMOVAL, aspSession);
                if (phpSession != null && phpSession.length() > 0)
                    newSn.setAttribute(RSSConfig.ATTR_PHPSESSIONREMOVAL, phpSession);
                if (bvSession != null && bvSession.length() > 0)
                    newSn.setAttribute(RSSConfig.ATTR_BVSESSIONREMOVAL, bvSession);
                ds.addChild(ds.getChildCount(), newSn);
            }
        }
        // Get the exclusions
        String exclusions = variableContext.getParameter(seqPrefix + "exclusions");
        if (exclusions != null) {
            // Delete existing exclusions record first
            int i = 0;
            while (i < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(i);
                if (sn.getType().equals(RSSConfig.NODE_EXCLUDES))
                    ds.removeChild(i);
                else
                    i++;
            }
            SpecificationNode cn = new SpecificationNode(RSSConfig.NODE_EXCLUDES);
            cn.setValue(exclusions);
            ds.addChild(ds.getChildCount(), cn);
        }
        // Read the feed timeout, if present
        String feedTimeoutValue = variableContext.getParameter(seqPrefix + "feedtimeout");
        if (feedTimeoutValue != null && feedTimeoutValue.length() > 0) {
            int j = 0;
            while (j < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(j);
                if (sn.getType().equals(RSSConfig.NODE_FEEDTIMEOUT))
                    ds.removeChild(j);
                else
                    j++;
            }
            SpecificationNode node = new SpecificationNode(RSSConfig.NODE_FEEDTIMEOUT);
            node.setAttribute(RSSConfig.ATTR_VALUE, feedTimeoutValue);
            ds.addChild(ds.getChildCount(), node);
        }
        // Read the feed refetch interval, if present
        String feedRefetchValue = variableContext.getParameter(seqPrefix + "feedrefetch");
        if (feedRefetchValue != null && feedRefetchValue.length() > 0) {
            int j = 0;
            while (j < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(j);
                if (sn.getType().equals(RSSConfig.NODE_FEEDRESCAN))
                    ds.removeChild(j);
                else
                    j++;
            }
            SpecificationNode node = new SpecificationNode(RSSConfig.NODE_FEEDRESCAN);
            node.setAttribute(RSSConfig.ATTR_VALUE, feedRefetchValue);
            ds.addChild(ds.getChildCount(), node);
        }
        // Read the minimum feed refetch interval, if present
        String minFeedRefetchValue = variableContext.getParameter(seqPrefix + "minfeedrefetch");
        if (minFeedRefetchValue != null && minFeedRefetchValue.length() > 0) {
            int j = 0;
            while (j < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(j);
                if (sn.getType().equals(RSSConfig.NODE_MINFEEDRESCAN))
                    ds.removeChild(j);
                else
                    j++;
            }
            SpecificationNode node = new SpecificationNode(RSSConfig.NODE_MINFEEDRESCAN);
            node.setAttribute(RSSConfig.ATTR_VALUE, minFeedRefetchValue);
            ds.addChild(ds.getChildCount(), node);
        }
        // Read the bad feed refetch interval (which is allowed to be null)
        String badFeedRefetchValuePresent = variableContext.getParameter(seqPrefix + "badfeedrefetch_present");
        if (badFeedRefetchValuePresent != null && badFeedRefetchValuePresent.length() > 0) {
            String badFeedRefetchValue = variableContext.getParameter(seqPrefix + "badfeedrefetch");
            int k = 0;
            while (k < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(k);
                if (sn.getType().equals(RSSConfig.NODE_BADFEEDRESCAN))
                    ds.removeChild(k);
                else
                    k++;
            }
            if (badFeedRefetchValue != null && badFeedRefetchValue.length() > 0) {
                SpecificationNode node = new SpecificationNode(RSSConfig.NODE_BADFEEDRESCAN);
                node.setAttribute(RSSConfig.ATTR_VALUE, badFeedRefetchValue);
                ds.addChild(ds.getChildCount(), node);
            }
        }
        // Read the dechromed mode
        String dechromedMode = variableContext.getParameter(seqPrefix + "dechromedmode");
        if (dechromedMode != null && dechromedMode.length() > 0) {
            int j = 0;
            while (j < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(j);
                if (sn.getType().equals(RSSConfig.NODE_DECHROMEDMODE))
                    ds.removeChild(j);
                else
                    j++;
            }
            SpecificationNode node = new SpecificationNode(RSSConfig.NODE_DECHROMEDMODE);
            node.setAttribute(RSSConfig.ATTR_MODE, dechromedMode);
            ds.addChild(ds.getChildCount(), node);
        }
        // Read the chromed mode
        String chromedMode = variableContext.getParameter(seqPrefix + "chromedmode");
        if (chromedMode != null && chromedMode.length() > 0) {
            int j = 0;
            while (j < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(j);
                if (sn.getType().equals(RSSConfig.NODE_CHROMEDMODE))
                    ds.removeChild(j);
                else
                    j++;
            }
            SpecificationNode node = new SpecificationNode(RSSConfig.NODE_CHROMEDMODE);
            node.setAttribute(RSSConfig.ATTR_MODE, chromedMode);
            ds.addChild(ds.getChildCount(), node);
        }
        // Now, do whatever action we were told to do.
        String rssop = variableContext.getParameter(seqPrefix + "rssop");
        if (rssop != null && rssop.equals("Add")) {
            // Add a match to the end
            String match = variableContext.getParameter(seqPrefix + "rssmatch");
            String map = variableContext.getParameter(seqPrefix + "rssmap");
            SpecificationNode node = new SpecificationNode(RSSConfig.NODE_MAP);
            node.setAttribute(RSSConfig.ATTR_MATCH, match);
            node.setAttribute(RSSConfig.ATTR_MAP, map);
            ds.addChild(ds.getChildCount(), node);
        } else if (rssop != null && rssop.equals("Delete")) {
            int index = Integer.parseInt(variableContext.getParameter(seqPrefix + "rssindex"));
            int j = 0;
            while (j < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(j);
                if (sn.getType().equals(RSSConfig.NODE_MAP)) {
                    if (index == 0) {
                        ds.removeChild(j);
                        break;
                    }
                    index--;
                }
                j++;
            }
        }
        String xc = variableContext.getParameter(seqPrefix + "tokencount");
        if (xc != null) {
            // Delete all tokens first
            int i = 0;
            while (i < ds.getChildCount()) {
                SpecificationNode sn = ds.getChild(i);
                if (sn.getType().equals(RSSConfig.NODE_ACCESS))
                    ds.removeChild(i);
                else
                    i++;
            }
            int accessCount = Integer.parseInt(xc);
            i = 0;
            while (i < accessCount) {
                String accessDescription = "_" + Integer.toString(i);
                String accessOpName = seqPrefix + "accessop" + accessDescription;
                xc = variableContext.getParameter(accessOpName);
                if (xc != null && xc.equals("Delete")) {
                    // Next row
                    i++;
                    continue;
                }
                // Get the stuff we need
                String accessSpec = variableContext.getParameter(seqPrefix + "spectoken" + accessDescription);
                SpecificationNode node = new SpecificationNode(RSSConfig.NODE_ACCESS);
                node.setAttribute(RSSConfig.ATTR_TOKEN, accessSpec);
                ds.addChild(ds.getChildCount(), node);
                i++;
            }
            String op = variableContext.getParameter(seqPrefix + "accessop");
            if (op != null && op.equals("Add")) {
                String accessspec = variableContext.getParameter(seqPrefix + "spectoken");
                SpecificationNode node = new SpecificationNode(RSSConfig.NODE_ACCESS);
                node.setAttribute(RSSConfig.ATTR_TOKEN, accessspec);
                ds.addChild(ds.getChildCount(), node);
            }
        }
        return null;
    }

    /**
     *  View specification.
     *  This method is called in the body section of a job's view page.  Its purpose is to present the document
     *  specification information to the user.  The coder can presume that the HTML that is output from
     *  this configuration will be within appropriate &lt;html&gt; and &lt;body&gt;tags.
     *  The connector will be connected before this method can be called.
     * @param out is the output to which any HTML should be sent.
     * @param locale is the locale the output is preferred to be in.
     * @param ds is the current document specification for this job.
     * @param connectionSequenceNumber is the unique number of this connection within the job.
