out.print(""<table class=\""displaytable\"">\n"" + ""  <tr><td class=\""separator\"" colspan=\""2\""><hr/></td></tr>\n"" + ""  <tr>\n"" + ""    <td class=\""description\""><nobr>"" + Messages.getBodyString(locale, ""RSSConnector.RobotsTxtUsageColon"") + ""</nobr></td>\n"" + ""    <td class=\""value\"">\n"" + ""      <select name=\""robotsusage\"" size=\""3\"">\n"" + ""        <option value=\""none\"" "" + (robotsUsage.equals(RSSConfig.VALUE_NONE) ? ""selected=\""selected\"""" : """") + "">"" + Messages.getBodyString(locale, ""RSSConnector.DontLookAtRobotsTxt"") + ""</option>\n"" + ""        <option value=\""data\"" "" + (robotsUsage.equals(RSSConfig.VALUE_DATA) ? ""selected=\""selected\"""" : """") + "">"" + Messages.getBodyString(locale, ""RSSConnector.ObeyRobotsTxtForDataFetchesOnly"") + ""</option>\n"" + ""        <option value=\""all\"" "" + (robotsUsage.equals(RSSConfig.VALUE_ALL) ? ""selected=\""selected\"""" : """") + "">"" + Messages.getBodyString(locale, ""RSSConnector.ObeyRobotsTxtForAllFetches"") + ""</option>\n"" + ""      </select>\n"" + ""    </td>\n"" + ""  </tr>\n"" + ""</table>\n"");
