"" + ""  if (editjob."" + seqPrefix + ""feedtimeout.value == \""\"" || !isInteger(editjob."" + seqPrefix + ""feedtimeout.value))\n"" + ""  {\n"" + ""    alert(\"""" + Messages.getBodyJavascriptString(locale, ""RSSConnector.ATimeoutValueInSecondsIsRequired"") + ""\"");\n"" + ""    editjob."" + seqPrefix + ""feedtimeout.focus();\n"" + ""    return false;\n"" + ""  }\n"" + ""  if (editjob."" + seqPrefix + ""feedrefetch.value == \""\"" || !isInteger(editjob."" + seqPrefix + ""feedrefetch.value))\n"" + ""  {\n"" + ""    alert(\"""" + Messages.getBodyJavascriptString(locale, ""RSSConnector.ARefetchIntervalInMinutesIsRequired"") + ""\"");\n"" + ""    editjob."" + seqPrefix + ""feedrefetch.focus();\n"" + ""    return false;\n"" + ""  }\n"" + ""  if (editjob."" + seqPrefix + ""minfeedrefetch.value == \""\"" || !isInteger(editjob."" + seqPrefix + ""minfeedrefetch.value))\n"" + ""  {\n"" + ""    alert(\"""" + Messages.getBodyJavascriptString(locale, ""RSSConnector.AMinimumRefetchIntervalInMinutesIsRequire"") + ""\"");\n"" + ""    editjob."" + seqPrefix + ""minfeedrefetch.focus();\n"" + ""    return false;\n"" + ""  }\n"" + ""  if (editjob."" + seqPrefix + ""badfeedrefetch.value != \""\"" && !isInteger(editjob."" + seqPrefix + ""badfeedrefetch.value))\n"" + ""  {\n"" + ""    alert(\"""" + Messages.getBodyJavascriptString(locale, ""RSSConnector.ABadFeedRefetchIntervalInMinutesIsRequired"") + ""\"");\n"" + ""    editjob."" + seqPrefix + ""badfeedrefetch.focus();\n"" + ""    return false;\n"" + ""  }\n"" + ""\n"" + ""  return true;\n"" + ""}\n"" + ""\n"" + ""//-->\n"" + ""</script>\n"");
