            result.append("    >>>").append(majorUpdatePattern).append("<<<\n");
        }
        result.append("  Minor Rules:\n");
        for (Pattern minorUpdatePattern : minorUpdatePatterns) {
            result.append("    >>>").append(minorUpdatePattern).append("<<<\n");
        }
